package aggregator

import (
	"encoding/json"
	"strconv"
	"strings"
	"time"
)

// Line is one parsed log line plus its provenance.
type Line struct {
	Service string
	Level   string
	Metrics map[string]float64
	TS      time.Time
}

// ParseLine parses a JSON log line:
//
//	{"ts":"2026-10-02T10:00:00Z","service":"auth","level":"INFO","latency_ms":12.3,"status":200}
//
// Any numeric field other than ts/service/level/message/msg is treated as a
// metric. ts is optional; on parse error the caller decides what to do.
func ParseLine(raw string) (Line, error) {
	var m map[string]any
	dec := json.NewDecoder(strings.NewReader(raw))
	dec.UseNumber()
	if err := dec.Decode(&m); err != nil {
		return Line{}, err
	}
	l := Line{Metrics: map[string]float64{}}
	if v, ok := m["service"].(string); ok {
		l.Service = v
	}
	if v, ok := m["level"].(string); ok {
		l.Level = strings.ToUpper(v)
	}
	if v, ok := m["ts"].(string); ok {
		if t, err := time.Parse(time.RFC3339Nano, v); err == nil {
			l.TS = t
		}
	}
	for k, v := range m {
		switch k {
		case "ts", "service", "level", "message", "msg":
			continue
		}
		switch n := v.(type) {
		case json.Number:
			if f, err := n.Float64(); err == nil {
				l.Metrics[k] = f
			}
		case float64:
			l.Metrics[k] = n
		}
	}
	return l, nil
}

var _ = strconv.Atoi
EOF
