package aggregator

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"sync"
)

// FileState is the persisted read position for one physical file identity.
type FileState struct {
	UID    uint64 `json:"uid"`
	Gen    int    `json:"gen"`
	Path   string `json:"path"`
	Inode  uint64 `json:"inode"`
	Offset int64  `json:"offset"`
	LineNo int64  `json:"line_no"`
}

// Event is one counted log line with full provenance.
type Event struct {
	Seq      int64              `json:"seq"`
	UID      uint64             `json:"uid"`
	Gen      int                `json:"gen"`
	Path     string             `json:"path"` // path as observed when the line was read
	Start    int64              `json:"start"`
	End      int64              `json:"end"`
	LineNo   int64              `json:"line_no"`
	Raw      string             `json:"raw"`
	Service  string             `json:"service"`
	Level    string             `json:"level"`
	Metrics  map[string]float64 `json:"metrics,omitempty"`
	ParseErr string             `json:"parse_err,omitempty"`
}

type commitFrame struct {
	CommittedBytes int64                 `json:"committed_bytes"`
	Offsets        map[string]*FileState `json:"offsets"`
}

// Store is a crash-safe, exactly-once event + offset store built on two
// append-only files:
//
//	events.log  - length/newline delimited Event records
//	commit.log  - JSON commit frames; the newest intact frame atomically
//	              declares both the durable prefix of events.log and the
//	              per-file offsets.
//
// Writes are fsynced before the commit frame is fsynced, so a kill at any
// point leaves either the old committed state or the new one, never a mix.
type Store struct {
	dir string

	mu        sync.Mutex
	events    *os.File
	commits   *os.File
	evBytes   int64 // durable (committed) length of events.log
	pendBytes int64 // current on-disk length including uncommitted appends
	seq       int64
	offsets   map[string]*FileState
}

func OpenStore(dir string) (*Store, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	s := &Store{dir: dir, offsets: map[string]*FileState{}}
	ev, err := os.OpenFile(filepath.Join(dir, "events.log"), os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return nil, s, err
	}
	cf, err := os.OpenFile(filepath.Join(dir, "commit.log"), os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		ev.Close()
		return nil, err
	}
	s.events, s.commits = ev, cf

	// Replay commit frames; the last intact one wins.
	sc := bufio.NewScanner(cf)
	sc.Buffer(make([]byte, 1024*1024), 64*1024*1024)
	var last commitFrame
	for sc.Scan() {
		var fr commitFrame
		if err := json.Unmarshal(sc.Bytes(), &fr); err != nil || fr.CommittedBytes < 0 {
			break // torn tail
		}
		last = fr
	}
	if last.Offsets != nil {
		s.offsets = last.Offsets
	}
	// Validate committed prefix of events.log and recover seq.
	fi, _ := ev.Stat()
	if last.CommittedBytes > fi.Size() {
		return nil, fmt.Errorf("store corrupt: commit points past events.log")
	}
	if last.CommittedBytes > 0 {
		if _, err := ev.Seek(last.CommittedBytes-1, io.SeekStart); err != nil {
			return nil, err
		}
		b := make([]byte, 1)
		if _, err := ev.ReadFull(b); err != nil || b[0] != '\n' {
			return nil, fmt.Errorf("store corrupt: committed prefix not line-aligned")
		}
		seq, err := s.maxSeqLocked(0, last.CommittedBytes)
		if err != nil {
			return nil, err
		}
		s.seq = seq
	}
	// Drop any uncommitted tail (events appended but never committed).
	if fi.Size() > last.CommittedBytes {
		if err := ev.Truncate(last.CommittedBytes); err != nil {
			return nil, err
		}
	}
	if _, err := ev.Seek(0, io.SeekEnd); err != nil {
		return nil, err
	}
	s.evBytes = last.CommittedBytes
	s.pendBytes = last.CommittedBytes
	return s, nil
}

func (s *Store) maxSeqLocked(from, to int64) (int64, error) {
	if _, err := s.events.Seek(from, io.SeekStart); err != nil {
		return 0, err
	}
	r := io.LimitReader(s.events, to-from)
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 1024*1024), 64*1024*1024)
	var max int64
	for sc.Scan() {
		var e Event
		if err := json.Unmarshal(sc.Bytes(), &e); err != nil {
			return 0, fmt.Errorf("store corrupt: %w", err)
		}
		if e.Seq > max {
			max = e.Seq
		}
	}
	return max, sc.Err()
}

// Offsets returns a snapshot copy of the committed per-file states.
func (s *Store) Offsets() map[string]FileState {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make(map[string]FileState, len(s.offsets))
	for k, v := range s.offsets {
		out[k] = *v
	}
	return out
}

// Commit appends events and new offsets as one atomic durable unit.
// Either all of it is visible after restart or none of it.
func (s *Store) Commit(evs []Event, offs map[string]*FileState) error {
	if len(evs) == 0 && len(offs) == 0 {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	batchStart := s.pendBytes
	for i := range evs {
		s.seq++
		evs[i].Seq = s.seq
		b, err := json.Marshal(evs[i])
		if err != nil {
			return err
		}
		if _, err := s.events.Write(append(b, '\n')); err != nil {
			return err
		}
		s.pendBytes += int64(len(b) + 1)
	}
	if err := s.events.Sync(); err != nil {
		return err
	}

	merged := make(map[string]*FileState, len(s.offsets)+len(offs))
	for k, v := range s.offsets {
		cp := *v
		merged[k] = &cp
	}
	for k, v := range offs {
		cp := *v
		merged[k] = &cp
	}
	fr := commitFrame{CommittedBytes: s.pendBytes, Offsets: merged}
	b, err := json.Marshal(fr)
	if err != nil {
		return err
	}
	if _, err := s.commits.Write(append(b, '\n')); err != nil {
		return err
	}
	if err := s.commits.Sync(); err != nil {
		return err
	}
	s.evBytes = s.pendBytes
	s.offsets = merged
	_ = batchStart
	return nil
}

// ScanEvents iterates committed events in order.
func (s *Store) ScanEvents(fn func(Event) error) error {
	s.mu.Lock()
	to := s.evBytes
	s.mu.Unlock()
	if _, err := s.events.Seek(0, io.SeekStart); err != nil {
		return err
	}
	r := io.LimitReader(s.events, to)
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 1024*1024), 64*1024*1024)
	for sc.Scan() {
		var e Event
		if err := json.Unmarshal(sc.Bytes(), &e); err != nil {
			return err
		}
		if err := fn(e); err != nil {
			return err
		}
	}
	return sc.Err()
}

func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	e1 := s.events.Close()
	e2 := s.commits.Close()
	return errors.Join(e1, e2)
}

// Stats is an aggregation result with provenance.
type Stats struct {
	LevelCounts map[string]int64            `json:"level_counts"`
	LevelLines  map[string][]EventRef       `json:"-"`
	Metrics     map[string]MetricAgg        `json:"metrics"`
	TotalLines  int64                       `json:"total_lines"`
	ParseErrors int64                       `json:"parse_errors"`
}

type EventRef struct {
	Path   string `json:"path"`
	LineNo int64  `json:"line_no"`
	UID    uint64 `json:"uid"`
	Gen    int    `json:"gen"`
	Start  int64  `json:"start"`
}

type MetricAgg struct {
	Count int64     `json:"count"`
	Sum   float64   `json:"sum"`
	Min   float64   `json:"min"`
	Max   float64   `json:"max"`
	Mean  float64   `json:"mean"`
	P50   float64   `json:"p50"`
	P95   float64   `json:"p95"`
	P99   float64   `json:"p99"`
	Lines []EventRef `json:"-"`
}

func refOf(e Event) EventRef {
	return EventRef{Path: e.Path, LineNo: e.LineNo, UID: e.UID, Gen: e.Gen, Start: e.Start}
}

// Query aggregates committed events, optionally filtered by service.
// Every returned number can be traced via the per-bucket line references.
func (s *Store) Query(service string) (map[string]*Stats, error) {
	out := map[string]*Stats{}
	add := func(svc string) *Stats {
		st := out[svc]
		if st == nil {
			st = &Stats{LevelCounts: map[string]int64{}, LevelLines: map[string][]EventRef{}, Metrics: map[string]MetricAgg{}}
			out[svc] = st
		}
		return st
	}
	vals := map[string]map[string][]float64{}
	err := s.ScanEvents(func(e Event) error {
		if service != "" && e.Service != service {
			return nil
		}
		st := add(e.Service)
		st.TotalLines++
		r := refOf(e)
		if e.ParseErr != "" {
			st.ParseErrors++
		}
		if e.Level != "" {
			st.LevelCounts[e.Level]++
			st.LevelLines[e.Level] = append(st.LevelLines[e.Level], r)
		}
		for k, v := range e.Metrics {
			ma := st.Metrics[k]
			if ma.Count == 0 {
				ma.Min, ma.Max = v, v
			}
			ma.Count++
			ma.Sum += v
			if v < ma.Min {
				ma.Min = v
			}
			if v > ma.Max {
				ma.Max = v
			}
			ma.Lines = append(ma.Lines, r)
			st.Metrics[k] = ma
			if vals[e.Service] == nil {
				vals[e.Service] = map[string][]float64{}
			}
			vals[e.Service][k] = append(vals[e.Service][k], v)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	for svc, st := range out {
		for k, ma := range st.Metrics {
			ma.Mean = ma.Sum / float64(ma.Count)
			vs := vals[svc][k]
			sort.Float64s(vs)
			ma.P50 = quantile(vs, 0.50)
			ma.P95 = quantile(vs, 0.95)
			ma.P99 = quantile(vs, 0.99)
			st.Metrics[k] = ma
		}
	}
	return out, nil
}

// nearest-rank quantile on a sorted slice
func quantile(sorted []float64, q float64) float64 {
	if len(sorted) == 0 {
		return 0
	}
	rank := int(q*float64(len(sorted)-1) + 0.5)
	if rank < 0 {
		rank = 0
	}
	if rank >= len(sorted) {
		rank = len(sorted) - 1
	}
	return sorted[rank]
}
EOF
echo ok"}

