package aggregator

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// Watcher tails *.log files in a directory, handling:
//   - rotation via rename (app.log -> app.log.1, new app.log appears)
//   - copy-truncate rotation (same inode, size shrinks)
//   - file deletion / appearance
//
// Identity of a physical stream:
//   UID  - stable identity for the pre-rotation file (hash of first bytes)
//   Gen  - generation: 0 = live file, 1..N = archived generations
//
// Archived files app.log.1 ... are drained to EOF and then forgotten only
// after their last committed line, so a kill mid-drain never loses or
// duplicates lines.
type Watcher struct {
	dir      string
	store    *Store
	poll     time.Duration
	stop     chan struct{}
	stopped  chan struct{}
	batchMax int
}

func NewWatcher(dir string, st *Store, poll time.Duration) *Watcher {
	return &Watcher{dir: dir, store: st, poll: poll, stop: make(chan struct{}), stopped: make(chan struct{}), batchMax: 256}
}

type openFile struct {
	state FileState
	f     *os.File
	arch  bool // archived: drain once and stop watching size changes
	done  bool
}

func (w *Watcher) Run() error {
	defer close(w.stopped)
	open := map[string]*openFile{} // key = "uid:gen"
	defer func() {
		for _, of := range open {
			of.f.Close()
		}
	}()
	t := time.NewTicker(w.poll)
	defer t.Stop()
	for {
		select {
		case <-w.stop:
			return nil
		case <-t.C:
		}
		if err := w.tick(open); err != nil {
			return err
		}
	}
}

func (w *Watcher) Stop() { close(w.stop); <-w.stopped }

func listLogFiles(dir string) (live []string, archives []string, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, nil, err
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".log") {
			live = append(live, filepath.Join(dir, name))
		} else if i := archiveGen(name); i > 0 {
			archives = append(archives, filepath.Join(dir, name))
		}
	}
	sort.Strings(live)
	sort.Strings(archives)
	return
}

// app.log.1 -> 1, app.log.10.gz -> 0 (compressed unsupported), app.log -> 0
func archiveGen(name string) int {
	idx := strings.Index(name, ".log.")
	if idx < 0 {
		return 0
	}
	suf := name[idx+5:]
	var g int
	for _, c := range suf {
		if c < '0' || c > '9' {
			return 0
		}
		g = g*10 + int(c-'0')
	}
	if g == 0 {
		return 0
	}
	return g
}

func uidFor(path string, f *os.File) (uint64, error) {
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return 0, err
	}
	h := sha256.New()
	h.Write([]byte(filepath.Base(path)))
	if _, err := io.CopyN(h, f, 4096); err != nil && err != io.EOF {
		return 0, err
	}
	var b [8]byte
	s := h.Sum(nil)
	copy(b[:], s[:8])
	return binary.BigEndian.Uint64(b[:]), nil
}

func (w *Watcher) tick(open map[string]*openFile) error {
	live, archives, err := listLogFiles(w.dir)
	if err != nil {
		return err
	}
	saved := w.store.Offsets()

	// Discover live files.
	for _, p := range live {
		if err := w.openLive(p, open, saved); err != nil {
			return err
		}
	}
	// Discover archives.
	for _, p := range archives {
		if err := w.openArchive(p, open, saved); err != nil {
			return err
		}
	}

	// Process every open handle.
	keys := make([]string, 0, len(open))
	for k := range open {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		of := open[k]
		if of.done {
			continue
		}
		consumed, err := w.drain(of)
		if err != nil {
			return err
		}
