package aggregator

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// Watcher tails *.log files in a directory, handling:
//   - rename rotation (app.log -> app.log.1, new app.log appears)
//   - copy-truncate rotation (same path/inode, size shrinks)
//   - file deletion / appearance
//
// Exactly-once semantics: offsets for a batch are durably committed in the
// same store transaction as the batch's events, so after a restart the
// watcher resumes at a line boundary that was either fully processed or not
// processed at all.
type Watcher struct {
	dir      string
	store    *Store
	poll     time.Duration
	stop     chan struct{}
	stopped  chan struct{}
	batchMax int
}

func NewWatcher(dir string, st *Store, poll time.Duration) *Watcher {
	return &Watcher{dir: dir, store: st, poll: poll, stop: make(chan struct{}), stopped: make(chan struct{}), batchMax: 256}
}

type openFile struct {
	key   string
	state FileState
	f     *os.File
	arch  bool // archived (app.log.N): drain once, then close
	inode uint64
}

func (w *Watcher) Run() error {
	defer close(w.stopped)
	open := map[string]*openFile{}
	defer func() {
		for _, of := range open {
			of.f.Close()
		}
	}()
	t := time.NewTicker(w.poll)
	defer t.Stop()
	for {
		select {
		case <-w.stop:
			return nil
		case <-t.C:
		}
		if err := w.tick(open); err != nil {
			return err
		}
	}
}

func (w *Watcher) Stop() { close(w.stop); <-w.stopped }

func listLogFiles(dir string) (live, archives []string, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, nil, err
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".log") {
			live = append(live, filepath.Join(dir, name))
		} else if g := archiveGen(name); g > 0 {
			archives = append(archives, filepath.Join(dir, name))
		}
	}
	sort.Strings(live)
	sort.Strings(archives)
	return
}

// app.log.1 -> 1 ; app.log / app.log.1.gz -> 0
func archiveGen(name string) int {
	idx := strings.Index(name, ".log.")
	if idx < 0 {
		return 0
	}
	g := 0
	for _, c := range name[idx+5:] {
		if c < '0' || c > '9' {
			return 0
		}
		g = g*10 + int(c-'0')
	}
	return g
}

func uidFor(path string, f *os.File) (uint64, error) {
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return 0, err
	}
	h := sha256.New()
	h.Write([]byte(filepath.Base(path)))
	if _, err := io.CopyN(h, f, 4096); err != nil && err != io.EOF {
		return 0, err
	}
	var b [8]byte
	copy(b[:], h.Sum(nil)[:8])
	return binary.BigEndian.Uint64(b[:]), nil
}

func stateKey(uid uint64, gen int) string {
	return keyOf(uid, gen)
}

func keyOf(uid uint64, gen int) string {
	return strings.Join([]string{itoa(uid), itoa64(int64(gen))}, ":")
}

func itoa(u uint64) string { return itoa64(int64(u)) }
func itoa64(i int64) string {
	if i == 0 {
		return "0"
	}
	neg := i < 0
	if neg {
		i = -i
	}
	var b [24]byte
	p := len(b)
	for i > 0 {
		p--
		b[p] = byte('0' + i%10)
		i /= 10
	}
	if neg {
		p--
		b[p] = '-'
	}
	return string(b[p:])
}

func (w *Watcher) tick(open map[string]*openFile) error {
	live, archives, err := listLogFiles(w.dir)
	if err != nil {
		return err
	}
	saved := w.store.Offsets()

	for _, p := range live {
		if err := w.openLive(p, open, saved); err != nil {
			return err
		}
	}
	for _, p := range archives {
		if err := w.openArchive(p, open, saved); err != nil {
			return err
		}
	}

	// Rename-style rotation: live handle's inode no longer matches the
	// inode at its path -> it became an archive; drain its remainder.
	for _, p := range live {
		if of := liveHandleFor(open, p); of != nil {
			fi, err := os.Stat(p)
			if err == nil && !os.SameFile(fi, fileInfo(of.f)) {
				of.arch = true
			}
		}
	}

	// Drain everything.
	for _, k := range sortedKeys(open) {
		of := open[k]
		if of.done {
			continue
		}
		more, err := w.drain(of)
		if err != nil {
			return err
		}
		if of.arch && !more {
			of.f.Close()
			of.done = true
			delete(open, k)
		}
	}
	return nil
}

func sortedKeys(m map[string]*openFile) []string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func liveHandleFor(open map[string]*openFile, path string) *openFile {
	for _, of := range open {
		if !of.arch && of.state.Path == path {
			return of
		}
	}
	return nil
}

func fileInfo(f *os.File) os.FileInfo {
	fi, _ := f.Stat()
	return fi
}

func (w *Watcher) openLive(path string, open map[string]*openFile, saved map[string]FileState) error {
	if liveHandleFor(open, path) != nil {
		return nil
	}
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	fi, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	st := FileState{Path: path}
	if fs := findSaved(saved, path); fs != nil {
		st = *fs
		if fi.Size() < st.Offset {
			// Copy-truncate: file restarted from zero.
			st.Offset, st.LineNo = 0, 0
			st.UID, st.Gen = 0, 0
		}
		if _, err := f.Seek(st.Offset, io.SeekStart); err != nil {
			f.Close()
			return err
		}
	}
	of := &openFile{state: st, f: f, inode: inodeOf(fi)}
	if st.UID == 0 {
		uid, err := uidFor(path, f)
		if err != nil {
			f.Close()
			return err
		}
		of.state.UID = uid
		if _, err := f.Seek(st.Offset, io.SeekStart); err != nil {
			f.Close()
			return err
		}
	}
	of.key = keyOf(of.state.UID, of.state.Gen)
	open[of.key] = of
	return nil
}

func (w *Watcher) openArchive(path string, open map[string]*openFile, saved map[string]FileState) error {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}
	fi, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	uid, err := uidFor(path, f)
	if err != nil {
		f.Close()
		return err
	}
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		f.Close()
		return err
	}
	gen := archiveGen(filepath.Base(path))
	st := FileState{UID: uid, Gen: gen, Path: path}
	key := keyOf(uid, gen)
	if _, exists := open[key]; exists {
		f.Close()
		return nil
	}
	if fs, ok := saved[key]; ok {
		if fs.Path == path {
			st = fs
		}
		if st.Offset >= fi.Size() {
			// Fully drained in an earlier run.
			f.Close()
			return nil
		}
		if _, err := f.Seek(st.Offset, io.SeekStart); err != nil {
			f.Close()
			return err
		}
	}
	open[key] = &openFile{key: key, state: st, f: f, arch: true, inode: inodeOf(fi)}
	return nil
}

func findSaved(saved map[string]FileState, path string) *FileState {
	for _, fs := range saved {
		if fs.Gen == 0 && fs.Path == path {
			return &fs
		}
	}
	return nil
}

// drain reads complete lines and commits each batch atomically with offsets.
// For archived files it returns false only at clean EOF; live files always
// return true (more may arrive later).
func (w *Watcher) drain(of *openFile) (bool, error) {
	var evs []Event
	offs := map[string]*FileState{}
	flush := func() error {
		if len(evs) == 0 {
			return nil
		}
		if err := w.store.Commit(evs, offs); err != nil {
			return err
		}
		evs = nil
		offs = map[string]*FileState{}
		return nil
	}

	buf := make([]byte, 64*1024)
	for {
		n, err := of.f.Read(buf)
		if n > 0 {
			chunk := buf[:n]
			for len(chunk) > 0 {
				nl := bytes.IndexByte(chunk, '\n')
				if nl < 0 {
					// Partial line: rewind so it is re-read next tick.
					if _, serr := of.f.Seek(-int64(len(chunk)), io.SeekCurrent); serr != nil {
						return false, serr
					}
					if err := flush(); err != nil {
						return false, err
					}
					return true, nil
				}
				start := of.state.Offset
				raw := strings.TrimRight(string(chunk[:nl]), "\r")
				of.state.Offset += int64(nl) + 1
				of.state.LineNo++
				ev := Event{
					UID:    of.state.UID,
					Gen:    of.state.Gen,
					Path:   of.state.Path,
					Start:  start,
					End:    of.state.Offset,
					LineNo: of.state.LineNo,
					Raw:    raw,
				}
				parsed, perr := ParseLine(raw)
				if perr != nil {
					ev.ParseErr = perr.Error()
				} else {
					ev.Service = parsed.Service
					ev.Level = parsed.Level
					ev.Metrics = parsed.Metrics
				}
				if ev.Service == "" {
					ev.Service = "_unknown"
				}
				evs = append(evs, ev)
				st := of.state
				offs[of.key] = &st
				chunk = chunk[nl+1:]
				if len(evs) >= w.batchMax {
					if err := flush(); err != nil {
						return false, err
					}
				}
			}
		}
		if err == io.EOF {
			if err := flush(); err != nil {
				return false, err
			}
			return !of.arch, nil
		}
		if err != nil {
			return false, err
		}
	}
