package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	"logagg/internal/aggregator"
)

func main() {
	if len(os.Args) < 2 {
		usage()
	}
	state := flag.String("state", "state", "state directory")
	flag.Parse()
	args := flag.Args()
	if len(args) < 1 {
		usage()
	}
	st, err := aggregator.OpenStore(*state)
	if err != nil {
		fatal(err)
	}
	defer st.Close()

	switch args[0] {
	case "stats":
		svc := ""
		if len(args) > 1 {
			svc = args[1]
		}
		res, err := st.Query(svc)
		if err != nil {
			fatal(err)
		}
		printStats(res)
	case "lines":
		// aggctl lines [service [level|metric=name]]
		var svc, level, metric string
		if len(args) > 1 {
			svc = args[1]
		}
		if len(args) > 2 {
			c := args[2]
			if len(c) > 7 && c[:7] == "metric=" {
				metric = c[7:]
			} else {
				level = c
			}
		}
		if err := st.ScanEvents(func(e aggregator.Event) error {
			if svc != "" && e.Service != svc {
				return nil
			}
			if level != "" && e.Level != level {
				return nil
			}
			if metric != "" {
				if _, ok := e.Metrics[metric]; !ok {
					return nil
				}
			}
			out := map[string]any{
				"service": e.Service, "level": e.Level, "path": e.Path,
				"line_no": e.LineNo, "start": e.Start, "raw": e.Raw,
			}
			if metric != "" {
				out["value"] = e.Metrics[metric]
			}
			b, _ := json.Marshal(out)
			fmt.Println(string(b))
			return nil
		}); err != nil {
			fatal(err)
		}
	case "offsets":
		for k, fs := range st.Offsets() {
			fmt.Printf("%s\t%s\tgen=%d\toffset=%d\tline=%d\n", k, fs.Path, fs.Gen, fs.Offset, fs.LineNo)
		}
	case "verify":
		// Exactly-once self check: every (uid,gen,start) appears once and
		// ranges cover [0,end) with no gaps.
		type span struct{ s, e int64 }
		groups := map[string][]span{}
		var total int64
		err := st.ScanEvents(func(e aggregator.Event) error {
			k := fmt.Sprintf("%d:%d", e.UID, e.Gen)
			groups[k] = append(groups[k], span{e.Start, e.End})
			total++
			return nil
		})
		if err != nil {
			fatal(err)
		}
		bad := false
		for k, sp := range groups {
			sortSpans(sp)
			var expect int64
			for _, s := range sp {
				if s.s != expect {
					fmt.Printf("GAP/OVERLAP %s: want start %d got %d\n", k, expect, s.s)
					bad = true
				}
				expect = s.e
			}
		}
		fmt.Printf("events=%d streams=%d exactly-once=%v\n", total, len(groups), !bad)
		if bad {
			os.Exit(1)
		}
	default:
		usage()
	}
}

type span struct{ s, e int64 }

func sortSpans(a []span) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j-1].s > a[j].s; j-- {
			a[j-1], a[j] = a[j], a[j-1]
		}
	}
}

func printStats(res map[string]*aggregator.Stats) {
	for svc, st := range res {
		fmt.Printf("service=%s lines=%d parse_errors=%d\n", svc, st.TotalLines, st.ParseErrors)
		for lvl, n := range st.LevelCounts {
			fmt.Printf("  level %-8s %d\n", lvl, n)
		}
		for name, m := range st.Metrics {
			fmt.Printf("  metric %-14s count=%d sum=%.4f min=%.4f mean=%.4f p50=%.4f p95=%.4f p99=%.4f max=%.4f\n",
				name, m.Count, m.Sum, m.Min, m.Mean, m.P50, m.P95, m.P99, m.Max)
		}
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: aggctl -state DIR <stats [service] | lines [service [LEVEL|metric=NAME]] | offsets | verify>")
	os.Exit(2)
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "error:", err)
	os.Exit(1)
}
