func renameRotate(dir, svc string) error {
	src := fmt.Sprintf("%s/%s.log", dir, svc)
	dst := fmt.Sprintf("%s/%s.log.1", dir, svc)
	if err := os.Rename(src, dst); err != nil {
		return err
	}
	// New empty live file.
	f, err := os.OpenFile(src, os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	return f.Close()
}

// truncateRotate simulates copy-truncate: content is archived by copy then
// the live file is truncated to zero (same inode).
func truncateRotate(dir, svc string) error {
	src := fmt.Sprintf("%s/%s.log", dir, svc)
	dst := fmt.Sprintf("%s/%s.log.t1", dir, svc)
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	if err := os.WriteFile(dst, data, 0o644); err != nil {
		return err
	}
	f, err := os.OpenFile(src, os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	if err := f.Truncate(0); err != nil {
		f.Close()
		return err
	}
	_, err = f.Seek(0, 0)
	f.Close()
	return err
}

func fatal(err error) {
	fmt.Fprintln(os.Stderr, "genlogs:", err)
	os.Exit(1)
}
