		t.Fatal(err)
	}
	if err := os.Truncate(live, 0); err != nil {
		t.Fatal(err)
	}
	write(20)
	time.Sleep(300 * time.Millisecond)

	// Kill N more times while data continues.
	for i := 0; i < killRestarts; i++ {
		w.Stop()
		st.Close()
		write(5)
		st, _ = OpenStore(state)
		w = NewWatcher(logs, st, 15*time.Millisecond)
		go w.Run()
		time.Sleep(60 * time.Millisecond)
	}

	waitFor(t, 5*time.Second, func() bool {
		var n int64
		st.ScanEvents(func(e Event) error { n++; return nil })
		return n == int64(totalSeq)
	})
	w.Stop()
	st.Close()

	// Note: auth.log.t1 is not an archive naming pattern so baseline must
	// exclude it; archiveGen(".t1") == 0 and suffix != .log, so excluded.
	want := baseline(t, logs)
	got := map[string]int64{}
	st2, _ := OpenStore(state)
	res, err := st2.Query("")
	if err != nil {
		t.Fatal(err)
	}
	for svc, s := range res {
		got[svc+"/TOTAL"] = s.TotalLines
		for lvl, n := range s.LevelCounts {
			got[svc+"/"+lvl] = n
		}
	}
	for k, v := range want {
		if got[k] != v {
			t.Errorf("count mismatch %s: baseline=%d aggregated=%d", k, v, got[k])
		}
	}
	if len(got) != len(want) {
		t.Errorf("bucket count mismatch: baseline=%v got=%v", want, got)
	}
	if got["auth/TOTAL"] != int64(totalSeq) {
		t.Fatalf("lost or duplicated lines: got %d want %d", got["auth/TOTAL"], totalSeq)
	}
}

