package aggregator

import (
	"bytes"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Watcher tails *.log files in a directory, handling:
//   - rename rotation (app.log -> app.log.1, new app.log appears)
//   - copy-truncate rotation (same path/inode, size shrinks)
//   - file deletion / appearance
//   - process kills at any point (offsets resumed from durable store)
//
// Stream identity is (inode, generation):
//   - rename preserves inode, so the renamed file keeps its identity and is
//     drained once as an archive;
//   - copy-truncate keeps the inode but restarts content, which bumps the
//     generation and resets the offset to 0;
//   - a new live file gets a new inode and starts at 0.
type Watcher struct {
	dir      string
	store    *Store
	poll     time.Duration
	stop     chan struct{}
	stopped  chan struct{}
	batchMax int
}

func NewWatcher(dir string, st *Store, poll time.Duration) *Watcher {
	return &Watcher{dir: dir, store: st, poll: poll, stop: make(chan struct{}), stopped: make(chan struct{}), batchMax: 256}
}

type openFile struct {
	done  bool
	state FileState
	f     *os.File
	arch  bool
}

func (w *Watcher) keyOf(st FileState) string {
	return strconv.FormatUint(st.Inode, 10) + ":" + strconv.Itoa(st.Gen)
}

func (w *Watcher) Run() error {
	defer close(w.stopped)
	open := map[string]*openFile{}
	defer func() {
		for _, of := range open {
			of.f.Close()
		}
	}()
	t := time.NewTicker(w.poll)
	defer t.Stop()
	for {
		select {
		case <-w.stop:
			return nil
		case <-t.C:
		}
		if err := w.tick(open); err != nil {
			return err
		}
	}
}

func (w *Watcher) Stop() { close(w.stop); <-w.stopped }

func listLogFiles(dir string) (live, archives []string, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, nil, err
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if strings.HasSuffix(name, ".log") {
			live = append(live, filepath.Join(dir, name))
		} else if g := archiveGen(name); g > 0 {
			archives = append(archives, filepath.Join(dir, name))
		}
	}
	sort.Strings(live)
	sort.Strings(archives)
	return
}

// app.log.1 -> 1 ; app.log / app.log.1.gz -> 0
func archiveGen(name string) int {
	idx := strings.Index(name, ".log.")
	if idx < 0 {
		return 0
	}
	g := 0
	for _, c := range name[idx+5:] {
		if c < '0' || c > '9' {
			return 0
		}
		g = g*10 + int(c-'0')
	}
	return g
}

func (w *Watcher) tick(open map[string]*openFile) error {
	live, archives, err := listLogFiles(w.dir)
	if err != nil {
		return err
	}
	saved := w.store.Offsets()

	for _, p := range live {
		if err := w.openByInode(p, false, open, saved); err != nil {
			return err
		}
	}
	for _, p := range archives {
		if err := w.openByInode(p, true, open, saved); err != nil {
			return err
		}
	}

	// Rename rotation: a live handle whose inode is no longer at its path
	// has been renamed to an archive. Re-point it and drain the remainder.
	for _, of := range open {
		if of.arch || of.done {
			continue
		}
		fi, err := os.Stat(of.state.Path)
		if err != nil {
			continue
		}
		if !os.SameFile(fi, fileInfo(of.f)) {
			if p := findPathByInode(append(append([]string{}, live...), archives...), inodeOf(fi)); p != "" {
				oldKey := w.keyOf(of.state)
				of.state.Path = p
				of.arch = true
				newKey := w.keyOf(of.state)
				delete(open, oldKey)
				open[newKey] = of
