			// Saved path no longer holds this inode; trust the current path.
			st.Gen = found.Gen
			st.Offset, st.LineNo = found.Offset, found.LineNo
		} else {
			st = *found
			st.Path = path
		}
		if fi.Size() < st.Offset {
			// Truncated while we were down: bump generation, restart.
			st.Offset, st.LineNo = 0, 0
			st.Gen++
		}
		if _, err := f.Seek(st.Offset, io.SeekStart); err != nil {
			f.Close()
			return err
		}
	}
	key := w.keyOf(st)
	// Archive already fully drained in a previous run.
	if arch && found != nil && st.Offset >= fi.Size() && fi.Size() > 0 {
		f.Close()
		return nil
	}
	if arch && found != nil && st.Offset >= fi.Size() && fi.Size() == 0 {
		f.Close()
		return nil
	}
	open[key] = &openFile{state: st, f: f, arch: arch}
	return nil
}

// drain reads complete lines, committing each batch atomically together
// with the new offsets. Partial trailing lines are left unread (seek back).
func (w *Watcher) drain(of *openFile) (bool, error) {
	var evs []Event
	offs := map[string]*FileState{}
	flush := func() error {
		if len(evs) == 0 {
			return nil
		}
		if err := w.store.Commit(evs, offs); err != nil {
			return err
		}
		evs = nil
		offs = map[string]*FileState{}
		return nil
	}

	buf := make([]byte, 64*1024)
	for {
		n, err := of.f.Read(buf)
		if n > 0 {
			chunk := buf[:n]
			for len(chunk) > 0 {
				nl := bytes.IndexByte(chunk, '\n')
				if nl < 0 {
					if _, serr := of.f.Seek(-int64(len(chunk)), io.SeekCurrent); serr != nil {
						return false, serr
					}
					if err := flush(); err != nil {
						return false, err
					}
					return true, nil
				}
				start := of.state.Offset
				raw := strings.TrimRight(string(chunk[:nl]), "\r")
				of.state.Offset += int64(nl) + 1
				of.state.LineNo++
				ev := Event{
					Inode:  of.state.Inode,
					Gen:    of.state.Gen,
					Path:   of.state.Path,
					Start:  start,
					End:    of.state.Offset,
					LineNo: of.state.LineNo,
					Raw:    raw,
				}
				parsed, perr := ParseLine(raw)
				if perr != nil {
					ev.ParseErr = perr.Error()
				} else {
					ev.Service = parsed.Service
					ev.Level = parsed.Level
					ev.Metrics = parsed.Metrics
				}
				if ev.Service == "" {
					ev.Service = "_unknown"
				}
				evs = append(evs, ev)
				st := of.state
				offs[w.keyOf(of.state)] = &st
				chunk = chunk[nl+1:]
				if len(evs) >= w.batchMax {
					if err := flush(); err != nil {
						return false, err
					}
				}
			}
		}
		if err == io.EOF {
			if err := flush(); err != nil {
				return false, err
			}
			return !of.arch, nil
		}
		if err != nil {
			return false, err
		}
	}
}
