package aggregator

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"testing"
	"time"
)

type rec struct {
	Service string  `json:"service"`
	Level   string  `json:"level"`
	Latency float64 `json:"latency_ms"`
	Seq     int     `json:"seq"`
}

func writeLine(t *testing.T, path, svc, lvl string, seq int, rng *rand.Rand) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	b, _ := json.Marshal(rec{svc, lvl, rng.Float64() * 100, seq})
	if _, err := f.Write(append(b, '\n')); err != nil {
		t.Fatal(err)
	}
}

// Full-scratch re-read of preserved files (live + numeric archives only).
// Content destroyed by copy-truncate is, by definition, not recoverable by
// a fresh reader, so truncation scenarios additionally compare against the
// test's own independent write tally below.
func scratchBaseline(t *testing.T, dir string) map[string]int64 {
	counts := map[string]int64{}
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		n := e.Name()
		if !endsWith(n, ".log") && archiveGen(n) == 0 {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, n))
		if err != nil {
			t.Fatal(err)
		}
		start := 0
		for i := 0; i <= len(data); i++ {
			if i == len(data) || data[i] == '\n' {
				if i > start {
					var r rec
					if json.Unmarshal(data[start:i], &r) == nil {
						counts[r.Service+"/"+r.Level]++
						counts[r.Service+"/TOTAL"]++
					}
				}
				start = i + 1
			}
		}
	}
	return counts
}

func endsWith(s, suf string) bool { return len(s) >= len(suf) && s[len(s)-len(suf):] == suf }

func countEvents(st *Store) int64 {
	var n int64
	st.ScanEvents(func(e Event) error { n++; return nil })
	return n
}

// spansContiguous checks exactly-once byte coverage per stream:
// every committed (inode,gen) covers [0,end) with no gap or overlap.
func spansContiguous(t *testing.T, st *Store) {
	groups := map[string][]pair{}
	st.ScanEvents(func(e Event) error {
		k := fmt.Sprintf("%d:%d", e.Inode, e.Gen)
		groups[k] = append(groups[k], pair{e.Start, e.End})
		return nil
	})
	for k, ps := range groups {
		// sort by start
		for i := 1; i < len(ps); i++ {
			for j := i; j > 0 && ps[j-1].a > ps[j].a; j-- {
				ps[j-1], ps[j] = ps[j], ps[j-1]
			}
		}
		var want int64
		for _, p := range ps {
			if p.a != want {
				t.Fatalf("stream %s gap/overlap: want %d got [%d,%d)", k, want, p.a, p.b)
			}
			want = p.b
		}
	}
}

