	written := map[string]int64{}
	var total int64

	st, err := OpenStore(state)
	if err != nil {
		t.Fatal(err)
	}
	w := NewWatcher(logs, st, 15*time.Millisecond)
	go w.Run()

	live := filepath.Join(logs, "auth.log")
