		for i := 0; i < n; i++ {
			lvl := levels[rng.Intn(len(levels))]
			total++
			written[lvl]++
			writeLine(t, live, "auth", lvl, int(total), rng)
		}
	}
	waitN := func(want int64) {
		deadline := time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			if countEvents(st) == want {
				return
			}
			time.Sleep(20 * time.Millisecond)
		}
		t.Fatalf("event count %d, want %d", countEvents(st), want)
	}

