		// already tailed, tail archives a copy then zeroes the file.
		write(15)
		time.Sleep(200 * time.Millisecond)
		data, err := os.ReadFile(live)
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(logs, "auth.log.t1"), data, 0o644); err != nil {
			t.Fatal(err)
		}
		if err := os.Truncate(live, 0); err != nil {
			t.Fatal(err)
		}
		write(20)
	}

