	for i := 0; i < killRestarts; i++ {
		w.Stop(); st.Close()
		write(5)
		st, _ = OpenStore(state)
		w = NewWatcher(logs, st, 15*time.Millisecond)
		go w.Run()
		time.Sleep(50 * time.Millisecond)
