	s := res["auth"]
	if s.TotalLines != total {
		t.Fatalf("total %d want %d", s.TotalLines, total)
	}
	for lvl, want := range written {
		if s.LevelCounts[lvl] != want {
			t.Errorf("level %s: aggregated=%d written=%d", lvl, s.LevelCounts[lvl], want)
		}
	}

