func TestExactlyOnceWithTruncate(t *testing.T)  { runScenario(t, 5, true) }
func TestExactlyOnceNoRestarts(t *testing.T)    { runScenario(t, 0, false) }

// A kill between event append and commit frame: uncommitted tail is
// discarded on reopen, committed offsets stay consistent.
func TestUncommittedTailDiscarded(t *testing.T) {
	state := t.TempDir()
	st, _ := OpenStore(state)
	evs := []Event{{Inode: 1, Path: "a.log", LineNo: 1, Start: 0, End: 2, Raw: "{}"}}
	if err := st.Commit(evs, map[string]*FileState{"1:0": {Inode: 1, Gen: 0, Path: "a.log", Offset: 2, LineNo: 1}}); err != nil {
		t.Fatal(err)
	}
	st.Close()

	f, err := os.OpenFile(filepath.Join(state, "events.log"), os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Fprintln(f, `{"inode":1,"raw":"junk"}`)
	f.Close()

	st2, err := OpenStore(state)
	if err != nil {
		t.Fatal(err)
	}
	if n := countEvents(st2); n != 1 {
		t.Fatalf("want 1 durable event, got %d", n)
	}
	off := st2.Offsets()
	if off["1:0"].Offset != 2 {
		t.Fatalf("offset not restored: %+v", off["1:0"])
	}
}
