cat > /Users/gbr/Downloads/coding-agent-eval/task7-log-aggregator/B/internal/aggregator/aggregator_test.go <<'EOF'
package aggregator

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"testing"
	"time"
)

type rec struct {
	Service string  `json:"service"`
	Level   string  `json:"level"`
	Latency float64 `json:"latency_ms"`
	Seq     int     `json:"seq"`
}

func writeLine(t *testing.T, path, svc, lvl string, seq int, rng *rand.Rand) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	b, _ := json.Marshal(rec{svc, lvl, rng.Float64() * 100, seq})
	if _, err := f.Write(append(b, '\n')); err != nil {
		t.Fatal(err)
	}
}

// Full-scratch re-read of preserved files (live + numeric archives only).
// Content destroyed by copy-truncate is, by definition, not recoverable by
// a fresh reader, so truncation scenarios additionally compare against the
// test's own independent write tally below.
func scratchBaseline(t *testing.T, dir string) map[string]int64 {
	counts := map[string]int64{}
	entries, _ := os.ReadDir(dir)
	for _, e := range entries {
		n := e.Name()
		if !endsWith(n, ".log") && archiveGen(n) == 0 {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, n))
		if err != nil {
			t.Fatal(err)
		}
		start := 0
		for i := 0; i <= len(data); i++ {
			if i == len(data) || data[i] == '\n' {
				if i > start {
					var r rec
					if json.Unmarshal(data[start:i], &r) == nil {
						counts[r.Service+"/"+r.Level]++
						counts[r.Service+"/TOTAL"]++
					}
				}
				start = i + 1
			}
		}
	}
	return counts
}

func endsWith(s, suf string) bool { return len(s) >= len(suf) && s[len(s)-len(suf):] == suf }

func countEvents(st *Store) int64 {
	var n int64
	st.ScanEvents(func(e Event) error { n++; return nil })
	return n
}

// spansContiguous checks exactly-once byte coverage per stream:
// every committed (inode,gen) covers [0,end) with no gap or overlap.
func spansContiguous(t *testing.T, st *Store) {
	groups := map[string][]pair{}
	st.ScanEvents(func(e Event) error {
		k := fmt.Sprintf("%d:%d", e.Inode, e.Gen)
		groups[k] = append(groups[k], pair{e.Start, e.End})
		return nil
	})
	for k, ps := range groups {
		// sort by start
		for i := 1; i < len(ps); i++ {
			for j := i; j > 0 && ps[j-1].a > ps[j].a; j-- {
				ps[j-1], ps[j] = ps[j], ps[j-1]
			}
		}
		var want int64
		for _, p := range ps {
			if p.a != want {
				t.Fatalf("stream %s gap/overlap: want %d got [%d,%d)", k, want, p.a, p.b)
			}
			want = p.b
		}
	}
}

type pair struct{ a, b int64 }

func runScenario(t *testing.T, killRestarts int, truncate bool) {
	logs := t.TempDir()
	state := filepath.Join(t.TempDir(), "state")
	rng := rand.New(rand.NewSource(42))
	levels := []string{"DEBUG", "INFO", "WARN", "ERROR"}

	// Independent tally of everything the generator wrote, by level.
	written := map[string]int64{}
	var total int64

	st, err := OpenStore(state)
	if err != nil {
		t.Fatal(err)
	}
	w := NewWatcher(logs, st, 15*time.Millisecond)
	go w.Run()

	live := filepath.Join(logs, "auth.log")
	write := func(n int) {
		for i := 0; i < n; i++ {
			lvl := levels[rng.Intn(len(levels))]
			total++
			written[lvl]++
			writeLine(t, live, "auth", lvl, int(total), rng)
		}
	}
	waitN := func(want int64) {
		deadline := time.Now().Add(5 * time.Second)
		for time.Now().Before(deadline) {
			if countEvents(st) == want {
				return
			}
			time.Sleep(20 * time.Millisecond)
		}
		t.Fatalf("event count %d, want %d", countEvents(st), want)
	}

	write(30)
	waitN(total)

	// Kill 1 while stopped, new lines arrive, then resume.
	w.Stop(); st.Close()
	write(20)
	st, _ = OpenStore(state)
	w = NewWatcher(logs, st, 15*time.Millisecond)
	go w.Run()
	waitN(total)

	// Rename rotation while stopped.
	w.Stop(); st.Close()
	write(10)
	if err := os.Rename(live, filepath.Join(logs, "auth.log.1")); err != nil {
		t.Fatal(err)
	}
	f, err := os.OpenFile(live, os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	f.Close()
	write(25)
	st, _ = OpenStore(state)
	w = NewWatcher(logs, st, 15*time.Millisecond)
	go w.Run()
	waitN(total)

	if truncate {
		// Copy-truncate while running; lines present at truncation were
		// already tailed, tail archives a copy then zeroes the file.
		write(15)
		time.Sleep(200 * time.Millisecond)
		data, err := os.ReadFile(live)
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(logs, "auth.log.t1"), data, 0o644); err != nil {
			t.Fatal(err)
		}
		if err := os.Truncate(live, 0); err != nil {
			t.Fatal(err)
		}
		write(20)
	}

	// Repeated kills while data keeps arriving.
	for i := 0; i < killRestarts; i++ {
		w.Stop(); st.Close()
		write(5)
		st, _ = OpenStore(state)
		w = NewWatcher(logs, st, 15*time.Millisecond)
		go w.Run()
		time.Sleep(50 * time.Millisecond)
	}
	waitN(total)
	w.Stop(); st.Close()

	st2, err := OpenStore(state)
	if err != nil {
		t.Fatal(err)
	}
	spansContiguous(t, st2)
	if got := countEvents(st2); got != total {
		t.Fatalf("lost/duplicated lines: aggregated=%d written=%d", got, total)
	}
	res, err := st2.Query("auth")
	if err != nil {
		t.Fatal(err)
	}
	s := res["auth"]
	if s.TotalLines != total {
		t.Fatalf("total %d want %d", s.TotalLines, total)
	}
	for lvl, want := range written {
		if s.LevelCounts[lvl] != want {
			t.Errorf("level %s: aggregated=%d written=%d", lvl, s.LevelCounts[lvl], want)
		}
	}

	if !truncate {
		// Rename-only scenario: a from-scratch full re-read must give the
		// identical result - the headline correctness check.
		base := scratchBaseline(t, logs)
		if base["auth/TOTAL"] != s.TotalLines {
			t.Fatalf("baseline=%d aggregated=%d", base["auth/TOTAL"], s.TotalLines)
		}
		for lvl, want := range written {
			if base["auth/"+lvl] != want {
				t.Fatalf("baseline level %s=%d written=%d", lvl, base["auth/"+lvl], want)
			}
		}
	}
}

func TestExactlyOnceRenameOnly(t *testing.T)    { runScenario(t, 5, false) }
func TestExactlyOnceWithTruncate(t *testing.T)  { runScenario(t, 5, true) }
func TestExactlyOnceNoRestarts(t *testing.T)    { runScenario(t, 0, false) }

// A kill between event append and commit frame: uncommitted tail is
// discarded on reopen, committed offsets stay consistent.
func TestUncommittedTailDiscarded(t *testing.T) {
	state := t.TempDir()
	st, _ := OpenStore(state)
	evs := []Event{{Inode: 1, Path: "a.log", LineNo: 1, Start: 0, End: 2, Raw: "{}"}}
	if err := st.Commit(evs, map[string]*FileState{"1:0": {Inode: 1, Gen: 0, Path: "a.log", Offset: 2, LineNo: 1}}); err != nil {
		t.Fatal(err)
	}
	st.Close()

	f, err := os.OpenFile(filepath.Join(state, "events.log"), os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Fprintln(f, `{"inode":1,"raw":"junk"}`)
	f.Close()

	st2, err := OpenStore(state)
	if err != nil {
		t.Fatal(err)
	}
	if n := countEvents(st2); n != 1 {
		t.Fatalf("want 1 durable event, got %d", n)
	}
	off := st2.Offsets()
	if off["1:0"].Offset != 2 {
		t.Fatalf("offset not restored: %+v", off["1:0"])
	}
}
EOF
